    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSource;
    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xFED124315443B60BULL + 0x8130692BC835B1ABULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0xAE59DD99616FCDFDULL + 0xA721A03CB982A9A5ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseC(pNonce * 0xF2966BF32476092DULL + 0xFD7864B77A60790AULL);
