            aOrbiterH = (aWandererF + RotL64(aCross, 54U)) + 0xBC8FDF0576A82721ULL;
            aOrbiterD = ((aWandererA + RotL64(aPrevious, 35U)) + 0xFA429AD0B8299D45ULL) + aTwistOrbiterAssignSaltE[((aIndex + 19U)) & S_SALT1];
            aOrbiterJ = ((aWandererD + RotL64(aIngress, 13U)) + RotL64(aCarry, 41U)) + 0x2CD59D5128111672ULL;
            aOrbiterI = (aWandererK + RotL64(aPrevious, 19U)) + 0xEEEC97A4A753A627ULL;
            aOrbiterC = (aWandererJ + RotL64(aScatter, 39U)) + 0x1046B58F1C23D589ULL;
            aOrbiterA = (aWandererI + RotL64(aIngress, 3U)) + 0x492B31EDCCDD303FULL;
            aOrbiterG = ((aWandererE + RotL64(aCross, 24U)) + RotL64(aCarry, 3U)) + 0xCE2899CB68F6534FULL;
            aOrbiterE = (aWandererG + RotL64(aScatter, 43U)) + 0x493F40E03C652318ULL;
            //
            aOrbiterB = ((aOrbiterB + aOrbiterH) + 0x203F1E914E472A0FULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0x25664D3145492BD0ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x21BCFEA6DA8882D3ULL), 13U);
            //
