            aOrbiterB = ((aWandererE + RotL64(aScatter, 29U)) + RotL64(aCarry, 5U)) + 0x1A2F3E943984FB15ULL;
            aOrbiterF = (aWandererC + RotL64(aIngress, 10U)) + 0xB4AB055939B9B4F4ULL;
