            //
            aOrbiterB = ((aOrbiterB + aOrbiterC) + 0x7E4AEC8FA36ACF51ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 6U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x4DDCB5EA89793B64ULL;
