            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterH = ((aWandererJ + RotL64(aIngress, 29U)) + 0x203B1CF2DE292748ULL) + aTwistOrbiterAssignSaltB[((aIndex + 5U)) & S_SALT1];
            aOrbiterI = (aWandererG + RotL64(aPrevious, 11U)) + 0x220EA613EE15FB48ULL;
            aOrbiterJ = (((aWandererF + RotL64(aScatter, 35U)) + RotL64(aCarry, 57U)) + 0x238F19B2A6774F95ULL) + aTwistOrbiterAssignSaltF[((aIndex + 25U)) & S_SALT1];
