            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterF) + 0x78726DA02709F3EEULL) + aTwistOrbiterUpdateSaltA[((aIndex + 20U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterJ) ^ 0xC65177E0E7EDEE3BULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xB12330A310B95211ULL), 35U);
