            aOrbiterC = (aOrbiterC + aOrbiterH) + 0xA0514AEABDA03AF4ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x2B706A2F3749D09EULL;
            aOrbiterG = RotL64((aOrbiterG * 0xCD87232C2FB3B7C1ULL), 3U);
