            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x0C8380E667F63CF9ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x0F7DAB17B2916FDFULL;
            aOrbiterH = RotL64((aOrbiterH * 0x608DC9541ED44501ULL), 23U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0x24F989E8DE1EA8D6ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterG) ^ 0x28F3EBDA424A2288ULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x0A584ECF49071ADBULL), 29U);
