            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x06B935C47643B405ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0xFD06BCA60A730A99ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xAD116F775687D395ULL), 43U);
