            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererF = aWandererF + ((((RotL64(aPrevious, 47U) + aOrbiterI) + RotL64(aOrbiterH, 29U)) + RotL64(aCarry, 21U)) + aTwistWandererUpdateSaltA[((aIndex + 15U)) & S_SALT1]);
