            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0x326429A8F2FEBA82ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x17B75B3AC2A53E0DULL), 57U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0x25642D307BD68989ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0x855270676DDFDED0ULL;
