            aWandererJ = aWandererJ + ((RotL64(aCross, 47U) + aOrbiterI) + RotL64(aOrbiterK, 4U));
            aWandererA = aWandererA ^ (((RotL64(aIngress, 5U) + aOrbiterJ) + RotL64(aOrbiterE, 57U)) + aKeyRotateAWandererUpdateSaltF[(((31U - aIndex) + 14U)) & S_SALT1]);
