            aOrbiterE = (aWandererF + RotL64(aIngress, 3U)) + 0xF078A739CE319428ULL;
            aOrbiterA = (((aWandererE + RotL64(aScatter, 29U)) + RotL64(aCarry, 19U)) + 0x5C9EC71C6A3B6F85ULL) + aKeyRotateAOrbiterAssignSaltF[(((31U - aIndex) + 24U)) & S_SALT1];
