            //
            aWandererB = aWandererB ^ (((RotL64(aIngress, 5U) + aOrbiterK) + RotL64(aOrbiterJ, 30U)) + aKeyRotateAWandererUpdateSaltC[((aIndex + 17U)) & S_SALT1]);
