            aWandererA = aWandererA + (((RotL64(aCross, 21U) + aOrbiterJ) + RotL64(aOrbiterG, 19U)) + aKeyRotateAWandererUpdateSaltE[(((31U - aIndex) + 25U)) & S_SALT1]);
