            aOrbiterB = (((aWandererJ + RotL64(aScatter, 3U)) + RotL64(aCarry, 43U)) + 0x505BF1F1DBB9F7D2ULL) + aKeyRotateAOrbiterAssignSaltA[((aIndex + 17U)) & S_SALT1];
