            aCross ^= (RotL64(aShadowLaneA[((S_BLOCK1 - aIndex + 11962U)) & S_BLOCK1], 24U) ^ RotL64(aKeyRowReadB[((aIndex + 13728U)) & W_KEY1], 37U));
