            //
            aOrbiterJ = ((aWandererF + RotL64(aIngress, 57U)) + RotL64(aCarry, 13U)) + 0x8A025EAE32981557ULL;
            aOrbiterH = (((aWandererE + RotL64(aPrevious, 29U)) + RotL64(aCarry, 35U)) + 0xC4D1542E724AA70AULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 24U)) & S_SALT1];
            aOrbiterC = (aWandererI + RotL64(aCross, 37U)) + 0x91036D184E0990EEULL;
            aOrbiterE = (aWandererH + RotL64(aScatter, 21U)) + 0xB5A43D6305E9BDECULL;
            aOrbiterF = (aWandererA + RotL64(aIngress, 12U)) + 0xDE2E4F608AB31CA6ULL;
            aOrbiterB = ((aWandererD + RotL64(aScatter, 47U)) + RotL64(aCarry, 47U)) + 0xBAC97EB655F9F073ULL;
            aOrbiterD = ((aWandererJ + RotL64(aPrevious, 5U)) + 0x62FB9432C187D89FULL) + aKeyRotateAOrbiterAssignSaltE[(((31U - aIndex) + 14U)) & S_SALT1];
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x09C75D25CF194C5DULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0x4B2DBBA29B930307ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x2DE70CDC18A5096DULL), 57U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterC) + 0xCA33CE75D903C25BULL) + aKeyRotateAOrbiterUpdateSaltD[((aIndex + 3U)) & S_SALT1];
