            aWandererC = aWandererC ^ (((RotL64(aIngress, 41U) + RotL64(aOrbiterK, 13U)) + aOrbiterB) + aKeyRotateBWandererUpdateSaltB[((aIndex + 5U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererG, 18U) ^ aWandererC);
