            //
            aOrbiterB = ((aOrbiterB + aOrbiterE) + 0xFAEDE438F2E09C2EULL) + aKeyRotateBOrbiterUpdateSaltD[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0xEB424A0DE0DC81B2ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xA75894DB454C48EDULL), 23U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0xC442162796A20A51ULL) + aKeyRotateBOrbiterUpdateSaltB[((aIndex + 28U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x5DE3D05A75A2FE5FULL;
            aOrbiterB = RotL64((aOrbiterB * 0x04E16F6209B8DAE1ULL), 51U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x82F6566A4EDDE6CAULL;
