            //
            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0x322F2BF620F349C5ULL) + aKeyRotateBOrbiterUpdateSaltC[((aIndex + 29U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0xE7B22880C7BF0346ULL;
